-- Individually verified club-only holiday notice; no inferred mobile coverage or department hours.
begin;
do $club$ declare bid uuid; applied jsonb; begin
if exists(select 1 from businesses where website ilike '%7684-lathrop%' or lower(name) like '%sam%club%' and city='Lathrop' or right(regexp_replace(coalesce(phone,''),'[^0-9]','','g'),10)='2093900324') then raise exception 'Duplicate Lathrop club';end if;
insert into businesses(name,category,city,address,phone,website,description,status,verified,claimed,rating,review_count,needs_review,source,source_url,verification_source,verified_at)values('Sam’s Club Lathrop #7684','Retail','Lathrop','16150 Golden Valley Parkway, Lathrop, CA 95330','(209) 390-0324','https://www.samsclub.com/club/7684-lathrop-ca','Membership warehouse club at 16150 Golden Valley Parkway. The official club page lists the warehouse closed Thursday, November 26, 2026 for the holiday; this dated club-hours notice was checked November 24. Confirm current shopping hours, membership requirements, inventory and pickup arrangements directly. Fuel, pharmacy and other departments have separate hours; their holiday schedules and delivery coverage are not established here.','approved',true,false,null,0,false,'editorial_first_party','https://www.samsclub.com/club/7684-lathrop-ca','first_party_website_desk_check',now())returning id into bid;
insert into listing_checks(business_id,source_url,checked_fields,service_areas,service_tags,scope_note)values(bid,'https://www.samsclub.com/club/7684-lathrop-ca',array['identity','club number','public phone','physical address','warehouse retail services','dated club holiday hours'],array['Lathrop'],array['warehouse shopping','grocery retail'],'Official club page freshly HTTP200 November 24, 2026: club7684 identity,16150GoldenValleyParkway,2093900324 and explicit Holiday Hours Thu Nov26 Closed. Physical Lathrop facility only, not mobile/delivery coverage to other cities. Closure applies to club-hours display, not separately confirmed fuel/pharmacy/other-department hours. No membership promotion, inventory, rating, quality or photo adopted. Recheck/remove time-sensitive notice after November26.');
select to_jsonb(b) into applied from businesses b where id=bid;
insert into directory_private.listing_corrections(business_id,previous_values,applied_values,reason,source_reference)values(bid,'{}'::jsonb,applied||jsonb_build_object('service_areas',array['Lathrop'],'holiday_scope','warehouse club only; Nov26 closure; recheck after date'),'Add independently checked Lathrop retail facility with dated holiday notice; do not infer department hours','https://www.samsclub.com/club/7684-lathrop-ca');
end $club$;
commit;
